import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { Layout, NavTree, theme } from '@atlantis/shared';
import type { NavEntry } from '@atlantis/shared';
import { CITIES } from './cities';
import type { City } from './cities';
import { useCityData } from './hooks';
import CitySelector from './components/CitySelector';
import CityOverview from './components/CityOverview';
import WeatherTimeline from './components/WeatherTimeline';
import AirQualityChart from './components/AirQualityChart';
import CityCompare from './components/CityCompare';

const SECTIONS: NavEntry[] = [
  {
    id: 'dashboard',
    name: 'Dashboard',
    icon: 'layout-grid',
    children: [
      { id: 'overview', name: 'City Overview', icon: 'map-pin' },
      { id: 'weather', name: 'Weather Timeline', icon: 'thermometer' },
      { id: 'air-quality', name: 'Air Quality', icon: 'wind' },
      { id: 'compare', name: 'Compare Cities', icon: 'bar-chart-2' },
    ],
  },
];

const Content = styled.div`
  padding: ${theme.spacing.xl};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.xl};
  max-width: 1400px;
  width: 100%;
`;

const Section = styled.section`
  scroll-margin-top: ${theme.spacing.lg};
`;

const Panel = styled.div`
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  padding: ${theme.spacing.lg};
`;

const SectionTitle = styled.h2`
  font-size: ${theme.typography.fontSizeLg};
  font-weight: 700;
  color: ${theme.colors.mainText};
  margin-bottom: ${theme.spacing.md};
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: ${theme.spacing.sm};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [activeSection, setActiveSection] = useState<string | null>(null);
  const [city, setCity] = useState<City>(CITIES[0]);
  const { snapshot, weather, airQuality, loading } = useCityData(city);

  const handleSelect = useCallback((entry: NavEntry) => {
    setActiveSection(entry.id);
    document.getElementById(entry.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const sidebar = <NavTree entries={SECTIONS} activeId={activeSection} onSelect={handleSelect} />;

  return (
    <Layout title="CityPulse" sidebar={sidebar} activeId={activeSection} topBarRight={topBarRight}>
      <Content>
        <Section id="overview">
          <SectionTitle>
            City Overview
            <CitySelector value={city.id} onChange={setCity} />
          </SectionTitle>
          <CityOverview snapshot={snapshot} loading={loading} />
        </Section>

        <Section id="weather">
          <Panel>
            <WeatherTimeline weather={weather} loading={loading} />
          </Panel>
        </Section>

        <Section id="air-quality">
          <Panel>
            <AirQualityChart airQuality={airQuality} loading={loading} />
          </Panel>
        </Section>

        <Section id="compare">
          <Panel>
            <CityCompare />
          </Panel>
        </Section>
      </Content>
    </Layout>
  );
}
